+
+fn selection_lines_from_text(text: &str) -> Vec<String> {
+    if text.is_empty() {
+        vec![String::new()]
+    } else {
+        text.lines().map(str::to_string).collect()
+    }
+}
+
+fn selected_text(
+    selection: &VisualSelection,
+    lines: &[String],
+    linewise_override: bool,
+) -> String {
+    let (start, end) = selection.normalized();
+    let mut copied = Vec::new();
+    for row in start.row..=end.row {
+        let Some(line) = lines.get(row) else {
+            continue;
+        };
+        if let Some((start_column, end_column)) =
+            selected_range_for_line(selection, row, line, linewise_override)
+        {
+            copied.push(slice_chars(line, start_column, end_column));
+        }
+    }
+
+    let mut text = copied.join("\n");
+    if linewise_override || selection.kind == VisualSelectionKind::Line {
+        text.push('\n');
+    }
+    text
+}
+
+fn selected_range_for_line(
+    selection: &VisualSelection,
+    row: usize,
+    line: &str,
+    linewise_override: bool,
+) -> Option<(usize, usize)> {
+    let (start, end) = selection.normalized();
+    if row < start.row || row > end.row {
+        return None;
+    }
+
+    let line_len = line_char_len(line);
+    if linewise_override || selection.kind == VisualSelectionKind::Line {
+        return Some((0, line_len));
+    }
+
+    match selection.kind {
+        VisualSelectionKind::Character if start.row == end.row => Some((
+            start.column.min(line_len),
+            end.column.saturating_add(1).min(line_len),
+        )),
+        VisualSelectionKind::Character if row == start.row => {
+            Some((start.column.min(line_len), line_len))
+        }
+        VisualSelectionKind::Character if row == end.row => {
+            Some((0, end.column.saturating_add(1).min(line_len)))
+        }
+        VisualSelectionKind::Character => Some((0, line_len)),
+        VisualSelectionKind::Block => {
+            let start_column = start.column.min(end.column).min(line_len);
+            let end_column = start
+                .column
+                .max(end.column)
+                .saturating_add(1)
+                .min(line_len);
+            Some((start_column, end_column))
+        }
+        VisualSelectionKind::Line => Some((0, line_len)),
+    }
+}
+
+fn slice_chars(text: &str, start: usize, end: usize) -> String {
+    text.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
+
+fn line_char_len(text: &str) -> usize {
+    text.chars().count()
+}
+
+fn max_selectable_column(text: &str) -> usize {
+    line_char_len(text).saturating_sub(1)
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] =
+        b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::with_capacity(bytes.len().div_ceil(3) * 4);
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = chunk.get(1).copied().unwrap_or(0);
+        let third = chunk.get(2).copied().unwrap_or(0);
+        encoded.push(TABLE[(first >> 2) as usize] as char);
+        encoded.push(TABLE[(((first & 0b0000_0011) << 4) | (second >> 4)) as usize] as char);
+        if chunk.len() > 1 {
+            encoded.push(TABLE[(((second & 0b0000_1111) << 2) | (third >> 6)) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+        if chunk.len() > 2 {
+            encoded.push(TABLE[(third & 0b0011_1111) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+    }
+    encoded
+}

